function collisionScene(){scene.updateMatrixWorld(true);const moving=new Set(dynamicMeshes);for(const a of Object.values(machines))for(const q of Object.values(a))if(q&&q.isObject3D)moving.add(q);for(const a of Object.values(guidedPushers))for(const q of Object.values(a))if(q&&q.isObject3D)moving.add(q);for(const q of [bricks,bulkFork,bulkBridge,bulkTrolley,bulkMast,mergeDeck,retention,...Object.values(carts),...Object.values(pallets)])moving.add(q);for(const q of Object.values(wells))for(const o of Object.values(q))moving.add(o);const out=[];function emit(o,b,i,matrix){if(b.isEmpty()||b.max.y<.001)return;o.geometry.computeBoundingBox();const local=o.geometry.boundingBox,center=local.getCenter(new T.Vector3()).applyMatrix4(matrix),size=local.getSize(new T.Vector3()),e=matrix.elements,axes=[new T.Vector3(e[0],e[1],e[2]),new T.Vector3(e[4],e[5],e[6]),new T.Vector3(e[8],e[9],e[10])],half=axes.map((v,a)=>v.length()*size.getComponent(a)/2);axes.forEach(v=>v.normalize());out.push({support_contact:!!o.userData.declineSupport,id:o.id+':'+i,min:b.min.toArray(),max:b.max.toArray(),type:o.geometry.type,center:center.toArray(),axes:axes.map(v=>v.toArray()),half});}scene.traverse(o=>{if(!o.isMesh||!o.visible)return;for(let p=o;p;p=p.parent)if(moving.has(p))return;if(o.isInstancedMesh){o.geometry.computeBoundingBox();const matrix=new T.Matrix4();for(let i=0;i<o.count;i++){o.getMatrixAt(i,matrix);matrix.premultiply(o.matrixWorld);emit(o,o.geometry.boundingBox.clone().applyMatrix4(matrix),i,matrix);}}else emit(o,new T.Box3().setFromObject(o),0,o.matrixWorld);});return out;}

window.GREENFIELD={collisionScene,retention,mergeDeck,travelMotor,paddleDrives:guidedPushers,centeringJaws,slideDrives,packClamps,pieceYaw,piecePitch,junctionActors,junctionDecks,discardBins:()=>Object.entries(carts).filter(([id])=>id.startsWith('DISCARD')).map(([id,o])=>({id,position:o.position.toArray(),rotation:o.rotation.y,opening:new T.Vector3(...(o.userData.receivingFaceLocal||[1,0,0])).applyQuaternion(o.quaternion).toArray()})),retentionState,assemblies:machines,components,showComponent,pickComponent,run:r,seek,position,pause(){playing=false;$('play').textContent='Play';},openCamera,view,snapshot(){return{time,webgl:!renderer.getContext().isContextLost(),renderedBricks:r.material.length,live,zones:zones.map(q=>({kind:q.kind,cell:q.cell,lane:q.lane,index:q.k,occupied:q.present,moving:q.moving,stopRaised:!IS_ZPA&&stopOpening([q.kind,q.cell,q.lane,q.k].join(':'),time)<.05,rollerDriveOn:q.moving})),cameraOpen:$('cameraPanel').open,drawCalls:renderer.info.render.calls};},renderer,scene,camera};window.GREENFIELD_READY=true;
